import { Rocket } from 'lucide-react';
import { useState } from 'react';

import type { Project } from '../../types/common';
import { CardGridSkeleton } from '../common/CardSkeleton';
import ShowMoreButton from '../core/ShowMoreButton';

import ProjectGrid from './ProjectGrid';

interface ProjectsProps {
  initialProjects: Project[];
  selectedTags: string[];
  isLoading?: boolean;
}

export default function Projects({ initialProjects, selectedTags, isLoading }: ProjectsProps) {
  const [showAll, setShowAll] = useState(false);

  // Show all projects if filtering is active or showAll is true
  const displayedProjects =
    selectedTags.length > 0 || showAll ? initialProjects : initialProjects.slice(0, 3);

  return (
    <section
      id="projects"
      className="py-8 bg-gradient-to-b from-white to-gray-50 dark:from-gray-900 dark:to-neutral-darker scroll-mt-24"
    >
      <div className="container mx-auto px-6">
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <Rocket className="w-8 h-8 text-primary dark:text-primary-light" />
            <h2 className="text-4xl font-bold text-neutral-dark dark:text-white">
              Featured Projects
            </h2>
          </div>
          {initialProjects.length > 3 && !selectedTags.length && (
            <ShowMoreButton showAll={showAll} onClick={() => setShowAll(!showAll)} />
          )}
        </div>

        {isLoading ? (
          <CardGridSkeleton />
        ) : displayedProjects.length > 0 ? (
          <ProjectGrid projects={displayedProjects} onTagClick={() => {}} />
        ) : (
          <div className="min-h-[400px] flex items-center justify-center bg-white dark:bg-neutral-dark rounded-xl">
            <p className="text-neutral-dark/70 dark:text-white/70">
              No results found. Try a different tag, or clear the filters to see all featured
              projects.
            </p>
          </div>
        )}
      </div>
    </section>
  );
}
